import hmac
import hashlib
import time
import struct
import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
DATABASE = '/tmp/tokens.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.execute('''CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            role TEXT NOT NULL DEFAULT 'user',
            active INTEGER NOT NULL DEFAULT 1
        )''')
        db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            action TEXT,
            timestamp REAL
        )''')
        db.commit()
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def generate_token(user_id, role, expires_in=3600):
    """Generate an authenticated token with user_id, role, and expiry."""
    expiry = int(time.time()) + expires_in
    # Pack: user_id (4 bytes signed int), expiry (4 bytes unsigned int), role_len (1 byte), role
    payload = struct.pack('<iI', user_id, expiry) + struct.pack('B', len(role)) + role.encode('utf-8')
    mac = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), payload, hashlib.sha256).digest()
    return (payload + mac).hex()

def verify_token(token_hex):
    """Verify token integrity and extract claims."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None

    if len(token_bytes) < 9 + 32:  # min: 4 + 4 + 1 + 0 + 32
        return None

    # Extract role_len to find payload boundary
    role_len = token_bytes[8]
    payload_end = 9 + role_len

    if len(token_bytes) < payload_end + 32:
        return None

    payload = token_bytes[:payload_end]
    provided_mac = token_bytes[payload_end:payload_end + 32]

    expected_mac = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), payload, hashlib.sha256).digest()

    if not hmac.compare_digest(provided_mac, expected_mac):
        return None

    user_id, expiry = struct.unpack('<iI', payload[:8])
    role = payload[9:9+role_len].decode('utf-8')

    return {'user_id': user_id, 'expiry': expiry, 'role': role}

def check_token_expiry(claims):
    """Check if token has expired. Returns True if token is still valid."""
    current_time = int(time.time())
    # Compare as unsigned integers - expiry is stored as unsigned
    return claims['expiry'] > current_time

def require_auth(f):
    """Decorator to require valid authentication."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        claims = verify_token(token)
        if claims is None:
            return jsonify({'error': 'Invalid token'}), 401
        if not check_token_expiry(claims):
            return jsonify({'error': 'Token expired'}), 401
        request.claims = claims
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    """Decorator to require admin role."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        if request.claims.get('role') != 'admin':
            return jsonify({'error': 'Forbidden'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/token', methods=['POST'])
def issue_token():
    """Issue a token for a valid user (simplified - normally would check password)."""
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Username required'}), 400

    db = get_db()
    user = db.execute('SELECT id, role FROM users WHERE username = ? AND active = 1',
                      (data['username'],)).fetchone()
    if not user:
        return jsonify({'error': 'User not found'}), 404

    token = generate_token(user[0], user[1])
    return jsonify({'token': token})

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def list_users():
    """Admin endpoint to list all users."""
    db = get_db()
    users = db.execute('SELECT id, username, role, active FROM users').fetchall()
    return jsonify({'users': [{'id': u[0], 'username': u[1], 'role': u[2], 'active': u[3]} for u in users]})

@app.route('/api/admin/delete_user', methods=['POST'])
@require_auth
@require_admin
def delete_user():
    """Admin endpoint to deactivate a user."""
    data = request.get_json()
    if not data or 'user_id' not in data:
        return jsonify({'error': 'user_id required'}), 400

    db = get_db()
    db.execute('UPDATE users SET active = 0 WHERE id = ?', (data['user_id'],))
    db.commit()

    # Audit log
    db.execute('INSERT INTO audit_log (user_id, action, timestamp) VALUES (?, ?, ?)',
               (request.claims['user_id'], f"deleted user {data['user_id']}", time.time()))
    db.commit()

    return jsonify({'status': 'ok'})

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    """Get current user's profile."""
    db = get_db()
    user = db.execute('SELECT id, username, role FROM users WHERE id = ?',
                      (request.claims['user_id'],)).fetchone()
    if not user:
        return jsonify({'error': 'User not found'}), 404
    return jsonify({'id': user[0], 'username': user[1], 'role': user[2]})

if __name__ == '__main__':
    app.run(debug=False, host='127.0.0.1', port=5000)
